133	func newTrailResumeCmd() *cobra.Command {
134		var opts trailResumeOptions
135	
136		cmd := &cobra.Command{
137			Use:   "resume [<trail>]",
138			Short: "Resume a trail's agent session",
139			Long: `Resume an agent session for a trail.
140	
141	The trail may be given as the first argument or via --trail, as a number, id, or
142	branch. Without one, the trail for the current branch is used.
143	
144	By default, interactive terminals show the trail context, restore the checkpoint
145	sessions on the trail branch, and ask whether Entire should start the agent. If
146	there are multiple sessions in the checkpoint, you can choose which one to
147	start. Non-interactive runs show the same context and print resume commands for
148	the latest checkpoint on the trail branch. Use --session or --checkpoint to
149	resume an exact session or checkpoint.
150	
151	Use --repo to assert the GitHub repository for copied commands, and --branch
152	with a trail number or id to assert the branch you expect the trail to be
153	attached to. If either assertion does not match the current checkout or trail,
154	resume stops before checking anything out.`,
155			Args: cobra.MaximumNArgs(1),
156			RunE: func(cmd *cobra.Command, args []string) error {
157				selector, err := parseOptionalTrailSelector(args, opts.Selector)
158				if err != nil {
159					return err
160				}
161				opts.Selector = selector
162				if err := validateTrailResumeOptions(opts); err != nil {
163					return err
164				}
165				external.DiscoverAndRegister(cmd.Context())
166				return runTrailResume(cmd, opts)
167			},
168		}
169	
170		cmd.Flags().StringVar(&opts.Selector, "trail", "", "Trail to resume (number, id, or branch; defaults to the current branch's trail)")
171		cmd.Flags().StringVar(&opts.ExpectedRepo, "repo", "", "Expected GitHub repository (owner/name); fails if the current checkout points elsewhere")
172		cmd.Flags().StringVar(&opts.ExpectedBranch, "branch", "", "Expected trail branch; fails if the trail is attached to a different branch")
173		cmd.Flags().StringVar(&opts.SessionID, "session", "", "Resume a specific known local session on the trail branch")
174		cmd.Flags().StringVar(&opts.CheckpointID, "checkpoint", "", "Resume a specific checkpoint on the trail branch")
175		cmd.Flags().BoolVarP(&opts.Force, "force", "f", false, "Skip prompts and overwrite existing session logs from checkpoints")
176		cmd.Flags().BoolVar(&opts.JSON, "json", false, "Output trail resume context as JSON")
177		cmd.Flags().BoolVar(&opts.NoResume, "no-resume", false, "Show trail resume context without restoring or resuming a session")
178	
179		return cmd
180	}
181	
182	func validateTrailResumeOptions(opts trailResumeOptions) error {
183		if strings.TrimSpace(opts.SessionID) != "" && strings.TrimSpace(opts.CheckpointID) != "" {
184			return errors.New("cannot combine --session and --checkpoint")
185		}
186		if opts.JSON && !opts.NoResume {
187			return errors.New("--json can only be used with --no-resume")
188		}
189		if opts.NoResume && (strings.TrimSpace(opts.SessionID) != "" || strings.TrimSpace(opts.CheckpointID) != "") {
190			return errors.New("cannot combine --no-resume with --session or --checkpoint")
191		}
192		if _, err := parseTrailResumeRepoFlag(opts.ExpectedRepo); err != nil {
193			return fmt.Errorf("validate --repo: %w", err)
194		}
195		if checkpointID := strings.TrimSpace(opts.CheckpointID); checkpointID != "" {
196			if err := id.Validate(checkpointID); err != nil {
197				return fmt.Errorf("validate --checkpoint: %w", err)
198			}
199		}
200		return nil
201	}
202	
203	func runTrailResume(cmd *cobra.Command, opts trailResumeOptions) error {
204		return runAuthenticatedDataAPI(cmd.Context(), cmd.ErrOrStderr(), trailInsecureHTTP(cmd), func(ctx context.Context, client *api.Client) error {
205			forge, owner, repo, err := resolveTrailRemote(ctx)
206			if err != nil {
207				return err
208			}
209			targetRepo := trailResumeRepository{Forge: forge, Owner: owner, Repo: repo}
210			expectedRepo, err := parseTrailResumeRepoFlag(opts.ExpectedRepo)
211			if err != nil {
212				return fmt.Errorf("validate --repo: %w", err)
213			}
214			if err := validateTrailResumeExpectedRepo(targetRepo, expectedRepo); err != nil {
215				return err
216			}
217			if expectedRepo.Repo != "" {
218				forge, owner, repo = expectedRepo.Forge, expectedRepo.Owner, expectedRepo.Repo
219			}
220	
221			found, err := resolveTrailBySelector(ctx, client, forge, owner, repo, opts.Selector, opts.ExpectedBranch)
222			if err != nil {
223				return err
224			}
225			branch := strings.TrimSpace(found.Branch)
226			if branch == "" {
227				return fmt.Errorf("%s has no branch to resume", describeTrailRef(found))
228			}
229			if err := validateTrailResumeExpectedBranch(found, opts.ExpectedBranch); err != nil {
230				return err
231			}
232	
233			sessions, sessionsSkipped, sessionErr := resolveTrailResumeSessionContexts(ctx, branch)
234			sessions, sessionsSkipped, sessionsUnavailable := knownTrailResumeSessionsForContext(sessions, sessionsSkipped, sessionErr)
235			if sessionsUnavailable != "" {
236				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: could not load trail checkpoint sessions: %s\n", sessionsUnavailable)
237			}
238	
239			findings, findingsErr := loadTrailResumeFindingsContext(ctx, client, found.ID)
240			if findingsErr != nil {
241				findings.Unavailable = findingsErr.Error()
242				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: could not load trail findings: %v\n", findingsErr)
243			}
244	
245			resumeCtx := buildTrailResumeContextForRepoWithSkipped(*found, sessions, sessionsUnavailable, sessionsSkipped, findings, owner+"/"+repo)
246			if opts.JSON {
247				return encodeTrailResumeContextJSON(cmd.OutOrStdout(), resumeCtx)
248			}
249	
250			printTrailResumeContext(cmd.OutOrStdout(), resumeCtx)
251			if opts.NoResume {
252				return nil
253			}
254	
255			if opts.CheckpointID != "" {
256				return resumeTrailCheckpoint(ctx, cmd, branch, id.CheckpointID(opts.CheckpointID), "", opts.Force)
257			}
258	
259			if opts.SessionID != "" {
260				sessionCtx, ok := findTrailResumeSession(resumeCtx.Sessions, opts.SessionID)
261				if ok {
262					return resumeTrailCheckpoint(ctx, cmd, branch, id.CheckpointID(sessionCtx.CheckpointID), opts.SessionID, opts.Force)
263				}
264				return resumeTrailLatest(ctx, cmd, branch, opts.Force, opts.SessionID)
265			}
266	
267			if interactive.CanPromptInteractively() && len(resumeCtx.Sessions) > 1 {
268				return runTrailResumePicker(ctx, cmd, branch, resumeCtx.Sessions, opts.Force)
269			}
270	
271			return resumeTrailLatest(ctx, cmd, branch, opts.Force, "")
272		})
273	}
