936	type trailResumeRestoredSessionChoice struct {
937		SessionID string
938		Label     string
939		Session   strategy.RestoredSession
940	}
941	
942	func buildTrailResumeRestoredSessionChoices(sessions []strategy.RestoredSession) []trailResumeRestoredSessionChoice {
943		sorted := append([]strategy.RestoredSession(nil), sessions...)
944		sort.SliceStable(sorted, func(i, j int) bool {
945			if trailRestoredSessionSortRank(sorted[i]) != trailRestoredSessionSortRank(sorted[j]) {
946				return trailRestoredSessionSortRank(sorted[i]) < trailRestoredSessionSortRank(sorted[j])
947			}
948			return sorted[i].CreatedAt.After(sorted[j].CreatedAt)
949		})
950	
951		choices := make([]trailResumeRestoredSessionChoice, 0, len(sorted))
952		for i, session := range sorted {
953			choices = append(choices, trailResumeRestoredSessionChoice{
954				SessionID: session.SessionID,
955				Label:     trailRestoredSessionChoiceLabel(session, i == 0 && len(sorted) > 1),
956				Session:   session,
957			})
958		}
959		return choices
960	}
