962	func trailRestoredSessionSortRank(session strategy.RestoredSession) int {
963		switch sessionpkg.Kind(session.Kind) {
964		case sessionpkg.KindAgentReview, sessionpkg.KindAgentInvestigate:
965			return 1
966		case sessionpkg.KindImported:
967			return 0
968		default:
969			if trailRestoredSessionLooksReviewLike(session) {
970				return 1
971			}
972			return 0
973		}
974	}
