976	func trailRestoredSessionChoiceLabel(session strategy.RestoredSession, isDefault bool) string {
977		prompt := trailRestoredSessionPrompt(session)
978		if prompt == "" {
979			prompt = trailResumeNoPrompt
980		} else {
981			prompt = stringutil.TruncateRunes(stringutil.CollapseWhitespace(prompt), 50, "...")
982		}
983		agentName := strings.TrimSpace(string(session.Agent))
984		if agentName == "" {
985			agentName = unknownAgentLabel
986		}
987		when := "-"
988		if !session.CreatedAt.IsZero() {
989			when = timeAgo(session.CreatedAt)
990		}
991		parts := []string{session.SessionID, prompt, agentName, "last active " + when}
992		if kindLabel := trailRestoredSessionKindLabel(session.Kind); kindLabel != "" {
993			parts = append(parts, kindLabel)
994		} else if trailRestoredSessionLooksReviewLike(session) {
995			parts = append(parts, "review")
996		}
997		if isDefault {
998			parts = append(parts, "default")
999		}
1000		return strings.Join(parts, " · ")
1001	}
