1023	func trailRestoredSessionLooksReviewLike(session strategy.RestoredSession) bool {
1024		prompt := strings.ToLower(trailRestoredSessionPrompt(session))
1025		return strings.HasPrefix(prompt, "review the code changes") ||
1026			strings.HasPrefix(prompt, "review this branch") ||
1027			strings.HasPrefix(prompt, "review the branch")
1028	}
1029	
1030	func trailRestoredSessionsAreAllReviewOrInvestigation(sessions []strategy.RestoredSession) bool {
1031		for _, session := range sessions {
1032			if trailRestoredSessionSortRank(session) == 0 {
1033				return false
1034			}
1035		}
1036		return len(sessions) > 0
1037	}
1038	
1039	func promptTrailRestoredSession(ctx context.Context, w io.Writer, sessions []strategy.RestoredSession) (strategy.RestoredSession, bool, error) {
1040		choices := buildTrailResumeRestoredSessionChoices(sessions)
1041		if len(choices) == 0 {
1042			return strategy.RestoredSession{}, false, nil
1043		}
1044	
1045		options := make([]huh.Option[string], 0, len(choices)+1)
1046		for _, choice := range choices {
1047			options = append(options, huh.NewOption(choice.Label, choice.SessionID))
1048		}
1049		options = append(options, huh.NewOption("Cancel", resumePickerCancel))
1050	
1051		selected := choices[0].SessionID
1052		form := NewAccessibleForm(
1053			huh.NewGroup(
1054				huh.NewSelect[string]().
1055					Title("Choose a checkpoint session to resume").
1056					Description("These are agent transcript logs restored from the branch checkpoint; they may not appear as trail UI sessions.").
1057					Options(options...).
1058					Value(&selected),
1059			),
1060		)
1061		if err := form.RunWithContext(ctx); err != nil {
1062			if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
1063				return strategy.RestoredSession{}, false, nil
1064			}
1065			return strategy.RestoredSession{}, false, fmt.Errorf("selection failed: %w", err)
1066		}
1067		if selected == "" || selected == resumePickerCancel {
1068			fmt.Fprintln(w, "Resume cancelled.")
1069			return strategy.RestoredSession{}, false, nil
1070		}
1071		for _, choice := range choices {
1072			if choice.SessionID == selected {
1073				return choice.Session, true, nil
1074			}
1075		}
1076		return strategy.RestoredSession{}, false, fmt.Errorf("invalid selection %q", selected)
1077	}
1078	
1079	func findTrailRestoredSession(sessions []strategy.RestoredSession, sessionID string) (strategy.RestoredSession, bool) {
1080		for _, session := range sessions {
1081			if session.SessionID == sessionID {
1082				return session, true
1083			}
1084		}
1085		return strategy.RestoredSession{}, false
