1087	
1088	func launchTrailRestoredSession(ctx context.Context, w io.Writer, session strategy.RestoredSession) error {
1089		resumeAgent, err := strategy.ResolveAgentForRewind(session.Agent)
1090		if err != nil {
1091			return fmt.Errorf("failed to resolve agent for session %s: %w", session.SessionID, err)
1092		}
1093		resumeCmd := resumeAgent.FormatResumeCommand(session.SessionID)
1094		cmd, ok, err := agent.NewResumeForegroundCommand(ctx, resumeAgent.Name(), session.SessionID)
1095		if !ok {
1096			fmt.Fprintf(w, "\nTo continue this session:\n")
1097			printSessionCommand(w, resumeCmd, session.Prompt, false, true)
1098			return nil
1099		}
1100		if err != nil {
1101			fmt.Fprintf(w, "\nCould not launch %s: %v\n", resumeCmd, err)
1102			fmt.Fprintf(w, "\nTo continue this session:\n")
1103			printSessionCommand(w, resumeCmd, session.Prompt, false, true)
1104			return nil
1105		}
1106		fmt.Fprintf(w, "\nLaunching: %s\n", resumeCmd)
1107		if err := cmd.Run(); err != nil {
1108			var exitErr *exec.ExitError
1109			if errors.As(err, &exitErr) {
1110				return nil
1111			}
1112			return fmt.Errorf("resume command failed: %w", err)
1113		}
1114		return nil
1115	}
1116	
1117	func runTrailResumePicker(ctx context.Context, cmd *cobra.Command, branch string, sessions []trailResumeSessionContext, force bool) error {
1118		if !ensureTrailResumeBranchAvailable(ctx, cmd.OutOrStdout(), branch) {
1119			return nil
1120		}
1121	
1122		options := make([]huh.Option[string], 0, len(sessions)+1)
1123		for _, session := range sessions {
1124			options = append(options, huh.NewOption(trailResumeSessionOptionLabel(session), session.SessionID))
1125		}
1126		options = append(options, huh.NewOption("Cancel", resumePickerCancel))
1127	
1128		selected := sessions[0].SessionID
1129		form := NewAccessibleForm(
1130			huh.NewGroup(
1131				huh.NewSelect[string]().
1132					Title("Choose a checkpoint session to resume").
1133					Description("These sessions are recorded in the trail branch checkpoint.").
1134					Options(options...).
1135					Value(&selected),
1136			),
1137		)
1138		if err := form.RunWithContext(ctx); err != nil {
1139			if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
1140				return nil
1141			}
1142			return fmt.Errorf("selection failed: %w", err)
1143		}
1144		if selected == "" || selected == resumePickerCancel {
1145			fmt.Fprintln(cmd.OutOrStdout(), "Resume cancelled.")
1146			return nil
1147		}
1148		sessionCtx, ok := findTrailResumeSession(sessions, selected)
1149		if !ok {
1150			return fmt.Errorf("invalid selection %q", selected)
1151		}
1152		return resumeTrailCheckpoint(ctx, cmd, branch, id.CheckpointID(sessionCtx.CheckpointID), sessionCtx.SessionID, force)
1153	}
1154	
1155	func ensureTrailResumeBranchAvailable(ctx context.Context, w io.Writer, branch string) bool {
1156		otherPath, ok := branchCheckedOutElsewhere(ctx, branch)
1157		if !ok {
1158			return true
1159		}
1160		fmt.Fprint(w, trailResumeWorktreeClashMessage(branch, otherPath))
1161		return false
1162	}
1163	
1164	func trailResumeWorktreeClashMessage(branch, otherPath string) string {
1165		var b strings.Builder
1166		fmt.Fprintf(&b, "Branch %q is already checked out in another worktree:\n", branch)
1167		fmt.Fprintf(&b, "  %s\n\n", otherPath)
1168		fmt.Fprintf(&b, "Resume from that worktree with:\n")
1169		fmt.Fprintf(&b, "  cd %s && entire trail resume %s\n", shellQuote(otherPath), shellArg(branch))
1170		return b.String()
