		t.Parallel()
		if reportErr := trailResumeReportErrorFrom(errors.New("dial tcp: connection refused")); reportErr != nil {
			t.Errorf("trailResumeReportErrorFrom() = %+v, want nil for untyped error", reportErr)
		}
	})
}

